def min_window(s, t):
    if not s or not t:
        return ''
    need = Counter(t)
    missing = len(t)
    best = ''
    left = 0
    for right, ch in enumerate(s, 1):
        if need[ch] > 0:
            missing -= 1
        need[ch] -= 1
        if missing == 0:
            while left < right and need[s[left]] < 0:
                need[s[left]] += 1
                left += 1
            if not best or right - left < len(best):
                best = s[left:right]
            need[s[left]] += 1
            missing += 1
            left += 1
    return best
